combined_tools = []
for server in connected_servers:
    tools = server.list_tools()  # each tool has name, description, input_schema
    for t in tools:
        t["server_id"] = server.id
        combined_tools.append(t)

def route(step_description, combined_tools, available_values, min_score=0.5):
    scored = []
    for tool in combined_tools:
        sim = embed_similarity(step_description, tool["description"])
        required = tool["input_schema"].get("required", [])
        fillable = all(field in available_values for field in required)
        if not fillable:
            continue
        scored.append((sim, tool))

    if not scored:
        return None  # nothing fits, caller must fall back

    scored.sort(key=lambda pair: pair[0], reverse=True)
    best_score, best_tool = scored[0]
    if best_score < min_score:
        return None
    return best_tool

best_tool = route(step_description, combined_tools, available_values)
if best_tool is None:
    return {
        "status": "no_tool_fits",
        "step": step_description,
        "message": "No connected tool matches this step, ask the user or revise the plan"
    }
call_tool(best_tool, ...)
